with sync_playwright() as p:
    browser = p.chromium.launch()
    context = browser.new_context(viewport={"width": 1100, "height": 1404}, device_scale_factor=3)
    page = context.new_page()
    page.goto(f"file://{html_path}")
    page.wait_for_timeout(5000)

    # Get bounding box of actual rendered content
    bbox = page.evaluate("""() => {
        const svgEl = document.querySelector('svg');
        if (svgEl) {
            const rect = svgEl.getBoundingClientRect();
            return { x: rect.x, y: rect.y, width: rect.width, height: rect.height };
        }
        // fallback: find first non-empty child of container
        const container = document.getElementById('container');
        const children = container.children;
        let minY = Infinity, maxY = 0, minX = Infinity, maxX = 0;
        for (let c of children) {
            const r = c.getBoundingClientRect();
            if (r.width > 0 && r.height > 0) {
                minX = Math.min(minX, r.left);
                minY = Math.min(minY, r.top);
                maxX = Math.max(maxX, r.right);
                maxY = Math.max(maxY, r.bottom);
            }
        }
        return { x: minX, y: minY, width: maxX - minX, height: maxY - minY };
    }""")
    print(f"Content bbox: {bbox}")

    raw_path = "/app/output/_raw.png"
    page.screenshot(path=raw_path, full_page=True)
    browser.close()

# Crop with PIL
